# Ambiguous patterns where two characters share identical command sequences
# Key: command sequence, Value: dict with decision rules (e.g. aspect ratio threshold)
AMBIGUOUS_PATTERNS = {
    # 'l' (lowercase L) vs 'I' (uppercase i):
    # In Comismsh.ttf, both share: MLLQLLQLLQLLQLLQLLQLLQLLQZMLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQZ
    # However, 'I' has aspect ratio w/h ~0.231, whereas 'l' has w/h ~0.220.
    'MLLQLLQLLQLLQLLQLLQLLQLLQZMLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQLLQZ': {
        'default': 'l',
        'disambiguate': lambda bbox: 'I' if (bbox[1] - bbox[0]) / max(bbox[3] - bbox[2], 1e-6) > 0.2255 else 'l'
    }
}
